```
Blazor.Boot.json will have an additional section that includes all available appsettings.* file. This helps avoid 404s

// boot.json
{
    "config": [
        "appSettings.Development.json",
        "appSettings.json"
    ]
}
```
```
// We have a middleware that adds a header for requests to blazor.boot.json

// Middleware - DevServer + Hosted template
if (app.IsDevelopment())
{
    app.Use(async (context, response) =>
    {
       response.Headers.Add("ComponentsWebAssemblyEnv", "Development"); 
    });
}
```

```ts
// Blazor.WebAssembly.ts

const response = await fetch('blazor.boot.json');
// Make it visible to user code?
const env = response.headers["ComponentsWebAssemblyEnv"] ?? 'Production';

if (boot.config) {
    // boot manifest contains filtered list
    boot.config.forEach(fetch);
    
    
    // boot manifest contains all files, but we filter on the client
    if (boot.config.contains("appsettings.json"))
        fetch('appsettings.json');
    
    if (env && boot.config.contains(`appsettings.${env}.json`)) {
        fetch(`appsettings.${env}.json`);
    
}
```

